// Flatten Deepgram words into timestamped lines the agent can cite directly.
// Contract: one line per sentence — "S<speaker> [start]: text" — where [start]
// is the EXACT audio time (seconds) of the first word on that line. Lines break
// at sentence ends, speaker changes, and silences > SILENCE_GAP, so a quote's
// timestamp is copied, never interpolated.
const words = $input.first().json.transcript_object ?? [];
const SILENCE_GAP = 3; // seconds

const lines = [];
let sentence = null;
let currentSpeaker = null;
let prevEnd = null;

const flush = () => {
  if (sentence && sentence.words.length) {
    lines.push(`S${sentence.speaker} [${sentence.start.toFixed(2)}]: ${sentence.words.join(' ')}`);
  }
  sentence = null;
};

for (const w of words) {
  const text = w.punctuated_word ?? w.word;
  const speaker = w.speaker ?? '?';
  const breaksLine =
    speaker !== currentSpeaker ||
    (prevEnd !== null && w.start - prevEnd > SILENCE_GAP);

  if (breaksLine) flush();
  if (!sentence) sentence = { speaker, start: w.start, words: [] };

  sentence.words.push(text);
  currentSpeaker = speaker;
  prevEnd = w.end;

  // sentence end: terminal ., !, or ? (allowing trailing closing quotes/brackets)
  if (/[.!?]["')\]]*$/.test(text)) flush();
}
flush();

// Also pass the last word's end time so the agent knows the total duration
const lastWord = words[words.length - 1];
return { transcript: lines.join('\n'), duration: lastWord ? lastWord.end : 0 };
